    def is_seq(x):
        return isinstance(x, (list, tuple))

    def clamp_dir(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(x, default=None):
        if is_seq(x) and len(x) >= 2:
            return x[0], x[1]
        return default

    def get_obs(key, default=None):
        if isinstance(observation, dict):
            return observation.get(key, default)
        return default

    def all_pos_from(value):
        out = []
        if is_seq(value):
            for item in value:
                p = pos(item)
                if p is not None:
                    out.append(p)
        return out

    def self_pos():
        for k in ("self_position", "agent_position", "player_position", "position"):
            p = pos(get_obs(k))
            if p is not None:
                return p
        return (0, 0)

    def opp_pos():
        for k in ("opponent_position", "enemy_position", "target_position"):
            p = pos(get_obs(k))
            if p is not None:
                return p
        for k in ("opponent_positions", "enemy_positions", "enemies"):
            lst = all_pos_from(get_obs(k, []))
            if lst:
                return lst[0]
        return None

    def size():
        w = get_obs("grid_width", get_obs("width", 0))
        h = get_obs("grid_height", get_obs("height", 0))
        try:
            w = int(w)
        except:
            w = 0
        try:
            h = int(h)
        except:
            h = 0
        return w, h

    def step_toward(a, b):
        return [clamp_dir(b[0] - a[0]), clamp_dir(b[1] - a[1])]

    def dist2(a, b):
        dx = a[0] - b[0]
        dy = a[1] - b[1]
        return dx * dx + dy * dy

    def manhattan(a, b):
        dx = a[0] - b[0]
        dy = a[1] - b[1]
        if dx < 0:
            dx = -dx
        if dy < 0:
            dy = -dy
        return dx + dy

    def valid_cell(c):
        return is_seq(c) and len(c) >= 2

    def best_of(cells, scorer):
        best = None
        best_score = None
        for c in cells:
            if not valid_cell(c):
                continue
            s = scorer(c)
            if best is None or s < best_score:
                best = c
                best_score = s
        return best

    env = get_obs("environment_name", "")
    me = self_pos()
    op = opp_pos()
    w, h = size()

    resources = []
    for k in ("resources", "resource_positions", "targets", "food", "collectibles"):
        items = get_obs(k, [])
        lst = all_pos_from(items)
        if lst:
            resources = lst
            break

    territory = []
